/**
 * 批量更新指定技能数据。
 * @param patches 需要更新的技能补丁列表。
 */
function patch(
    patches: Array<{ id: number; skillName: string; data: Partial<Char["技能"][number]> }>,
    cb: (skill: Char["技能"][number], patch: { id: number; skillName: string; data: Partial<Char["技能"][number]> }) => void
) {
    for (const patch of patches) {
        for (const char of t) {
            if (char.id !== patch.id) {
                continue
            }
            const skill = char.技能.find(item => item.名称 === patch.skillName)
            if (!skill) {
                break
            }
            cb(skill, patch)
            break
        }
    }
}

/**
 * 批量更新指定角色数据。
 * @param patches 需要更新的角色补丁列表。
 */
function patchUW(
    patches: Array<{ id: number; data: Partial<Char> | ((uw: Char) => Partial<Char>) }>,
    cb: (uw: Char, patch: { id: number; data: Partial<Char> | ((uw: Char) => Partial<Char>) }) => void
) {
    for (const patch of patches) {
        for (const char of t) {
            if (char.id !== patch.id) {
                continue
            }
            cb(char, patch)
            break
        }
    }
}

/**
 * 批量写入专武字段。
 */
function patchCWeapon() {
    const table = [
        { id: 4202, 专武: 10104 },
        { id: 2301, 专武: 10102 },
        { id: 2101, 专武: 10201 },
        { id: 4301, 专武: 10501 },
        { id: 1103, 专武: 20405 },
        { id: 3201, 专武: 10301 },
    ]
    patchUW(
        [
            ...table.map(item => ({ id: item.id, data: { 专武: item.专武 } })),
            {
                id: 5301,
                data: uw => ({
                    同律武器: [
                        {
                            ...uw.同律武器![0],
                            攻速: 1 / 0.3,
                        },
                    ],
                }),
            },
            {
                id: 1101, // 贝蕾妮卡
                data: uw => ({
                    技能: uw.技能.map(skill => {
                        if (skill.id === 110102) {
                            skill.字段 = [
                                ...skill.字段!,
                                {
                                    名称: "充盈伤害",
                                    值: 15,
                                    tag: ["近战", "武器", "普攻", "同律", "充盈"],
                                },
                            ]
                        }
                        return skill
                    }),
                }),
            },
            {
                id: 1102,
                data: {
                    同律武器: [
                        {
                            id: 110200,
                            名称: "圆舞",
                            skill: [0, 1, 2],
                            类型: ["同律", "近战", "单手剑"],
                            inherit: "melee",
                            atk: "all",
                        },
                    ],
                },
            },
            {
                id: 1503,
                data: {
                    同律武器: [
                        {
                            id: 150300,
                            名称: "剑非剑",
                            类型: ["同律", "近战", "单手剑"],
                            filter: "霜剑拂流星",
                            inherit: "melee",
                        },
                    ],
                },
            },
            {
                id: 4201,
                data: {
                    同律武器: [
                        {
                            id: 420110,
                            名称: "疑星落",
                            类型: ["同律", "近战", "长柄"],
                            skill: [0],
                            filter: "疑星落|星河寥落",
                            inherit: "melee",
                            atk: "all",
                            视为: "下落攻击",
                        },
                    ],
                },
            },
        ],
        (char, patch) => {
            if (typeof patch.data === "function") {
                Object.assign(char, patch.data(char))
                return
            }
            Object.assign(char, patch.data)
        }
    )
}

